const jobs = new Map(); // job_id -> status

export async function listTools() {
  return [
    {
      name: 'start_job',
      description: 'Start a job with the given job_id. Returns running status. Rejects duplicate active jobs.',
      inputSchema: {
        type: 'object',
        properties: {
          job_id: { type: 'string', description: 'Unique identifier for the job.' }
        },
        required: ['job_id'],
        additionalProperties: false
      }
    },
    {
      name: 'cancel_job',
      description: 'Cancel an active job with the given job_id. Rejects missing jobs or repeated cancellation.',
      inputSchema: {
        type: 'object',
        properties: {
          job_id: { type: 'string', description: 'Unique identifier for the job to cancel.' }
        },
        required: ['job_id'],
        additionalProperties: false
      }
    }
  ];
}

function requireJobId(args) {
  if (args == null || typeof args !== 'object') {
    throw new Error('Arguments must be an object');
  }
  const { job_id } = args;
  if (typeof job_id !== 'string' || job_id.length === 0) {
    throw new Error('job_id is required and must be a non-empty string');
  }
  return job_id;
}

function textResult(text) {
  return { content: [{ type: 'text', text }] };
}

export async function callTool(name, args = {}) {
  switch (name) {
    case 'start_job': {
      const job_id = requireJobId(args);
      if (jobs.get(job_id) === 'running') {
        const err = new Error(`Job ${job_id} is already running`);
        err.code = -32602;
        throw err;
      }
      jobs.set(job_id, 'running');
      return textResult(`Job ${job_id} is running`);
    }
    case 'cancel_job': {
      const job_id = requireJobId(args);
      const status = jobs.get(job_id);
      if (status === undefined) {
        const err = new Error(`Job ${job_id} not found`);
        err.code = -32602;
        throw err;
      }
      if (status === 'cancelled') {
        const err = new Error(`Job ${job_id} is already cancelled`);
        err.code = -32602;
        throw err;
      }
      jobs.set(job_id, 'cancelled');
      return textResult(`Job ${job_id} is cancelled`);
    }
    default:
      throw new Error(`Unknown tool: ${name}`);
  }
}
